        await page.wait_for_load_state("networkidle")
    except Exception as e:
        return f"Failed to click project link: {e}"

    # Step 2: After navigation, look for a 'Settings' or 'Members' link to manage invitations
    # Assuming typical GitLab structure, try 'Settings' first
    try:
        settings_link = page.get_by_role("link", name="Settings", exact=True)
        await settings_link.click()
        await page.wait_for_load_state("networkidle")
    except Exception as e:
        # If 'Settings' not found, try 'Members'
        try:
            members_link = page.get_by_role("link", name="Members", exact=True)
            await members_link.click()
            await page.wait_for_load_state("networkidle")
        except Exception as e2:
            return f"Neither Settings nor Members link found: {e2}"

    # Step 3: On the settings/members page, find and click 'Invite members' button
    try:
        invite_button = page.get_by_role("button", name="Invite members", exact=True)
        await invite_button.click()
        await page.wait_for_load_state("networkidle")
    except Exception as e:
        return f"Invite members button not found: {e}"

    # Step 4: Fill in the invite form for Abishek as a guest
    try:
        username_input = page.get_by_role("textbox", name="Username or email", exact=True)
        await username_input.fill("Abishek")
    except Exception as e:
        return f"Username input not found: {e}"

    try:
        role_dropdown = page.get_by_role("combobox", name="Role", exact=True)
        await role_dropdown.select_option("Guest")
    except Exception as e:
        return f"Role dropdown not found: {e}"

    # Step 5: Click the invite button to send the invitation
    try:
        submit_button = page.get_by_role("button", name="Invite", exact=True)
        await submit_button.click()
        await page.wait_for_load_state("networkidle")
    except Exception as e:
        return f"Invite button not found: {e}"

    # Step 6: Check for a success message and return result
    try:
        success_message = page.get_by_text("Invitation sent", exact=True)
        if await success_message.is_visible():
            return "Invitation sent to Abishek as guest."
        else:
            return "Invitation process completed, but no confirmation message visible."
    except Exception as e:
        return f"Error checking success message: {e}"

